#![cfg(unix)]

//! Opt-in source-to-runtime integration. Supply the `.klbc` and `.kirb`
//! generated by a rebuilt Kira compiler from the `remote-plugin` corpus.
//! Regular tests need no installed Kira compiler or SDK.

use klf_helper_apps::{Artifact, Catalog, Host, InstalledApp, PluginId, Service};
use klf_ridl::meta::{AbiEntry, AbiStatus, ImportReq, Metadata};
use klf_ridl_wire::{Reply, Value};
use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::Arc;
use std::sync::atomic::{AtomicUsize, Ordering};

#[test]
#[ignore = "full Kira std imports need per-plugin runtime capability policy and native-library isolation"]
fn compiled_kira_plugin_imports_a_generated_host_package_and_activates() {
    let Ok(image) = std::env::var("KLF_COMPILED_KIRA_PLUGIN_IMAGE") else {
        eprintln!("source-level Kira plugin test requires KLF_COMPILED_KIRA_PLUGIN_IMAGE");
        return;
    };
    let kir = std::env::var("KLF_COMPILED_KIRA_PLUGIN_KIRB")
        .expect("set KLF_COMPILED_KIRA_PLUGIN_KIRB when specifying a compiled Kira plugin");
    let folder = std::env::temp_dir().join(format!("klf-source-plugin-{}", std::process::id()));
    std::fs::create_dir_all(&folder).unwrap();
    let metadata_file = folder.join("plugin.ridlmeta");
    let import = Metadata {
        module_name: "RemoteMarketplacePlugin".into(),
        abis: vec![],
        imports: vec![ImportReq {
            module: "Harmony".into(),
            required: [7; 16],
        }],
        sha256: [0; 32],
        unmanaged: vec![],
    };
    std::fs::write(&metadata_file, import.encode()).unwrap();

    let mut catalog = Catalog::default();
    catalog
        .set_vm_runtime(PathBuf::from(env!("CARGO_BIN_EXE_klf-helper-vm")))
        .unwrap();
    let id = PluginId::new("marketplace.compiled-kira").unwrap();
    catalog
        .install(
            id.clone(),
            InstalledApp::from_compiled(
                Artifact::Vm {
                    image: image.into(),
                    kir: kir.into(),
                },
                metadata_file,
            )
            .unwrap(),
        )
        .unwrap();

    let calls = Arc::new(AtomicUsize::new(0));
    let mut functions: HashMap<String, Service> = HashMap::new();
    let seen = Arc::clone(&calls);
    functions.insert(
        "enabled".into(),
        Arc::new(move |args| {
            assert!(args.is_empty());
            seen.fetch_add(1, Ordering::Relaxed);
            Reply::Returned(Value::Bool(true))
        }),
    );
    let seen = Arc::clone(&calls);
    functions.insert(
        "add".into(),
        Arc::new(move |args| {
            assert_eq!(args, [Value::Int(2), Value::Int(40)]);
            seen.fetch_add(1, Ordering::Relaxed);
            Reply::Returned(Value::Int(42))
        }),
    );
    let mut host = Host::default();
    host.export(
        Metadata {
            module_name: "Harmony".into(),
            abis: vec![AbiEntry {
                uuid: [7; 16],
                status: AbiStatus::Current,
            }],
            imports: vec![],
            sha256: [0; 32],
            unmanaged: vec![],
        },
        functions,
    )
    .unwrap();
    let plugin = host.start_managed(&catalog, &id).unwrap();
    let exit = plugin.wait().unwrap();
    assert!(exit.success(), "Kira plugin runner exited with {exit}");
    assert_eq!(calls.load(Ordering::Relaxed), 2);
    std::fs::remove_dir_all(folder).unwrap();
}
